
import React, {Component} from 'react';
import Title from '../../components/Title';
import "../../Pages/Styling/About.css"

import SpectrogramPlayer from "react-audio-spectrogram-player";

import Blog6Img from "../../components/assets/Blogs/Images/Blog6.jpg"
import Blog6Img_1 from "../../components/assets/Blogs/Images/Blog6_1.jpg"
import Blog6Img_2 from "../../components/assets/Blogs/Images/Blog6_2.jpg"

import Blog6_Audio1 from "../../components/assets/Blogs/Audios/Blog6_Audio1.mp3"
import Blog6_Audio2 from "../../components/assets/Blogs/Audios/Blog6_Audio2.mp3"
import Blog6_Audio3 from "../../components/assets/Blogs/Audios/Blog6_Audio3.mp3"


class Blog6 extends Component {
  render() {
    return (
      <div className="centre">
        <Title title="The battle between Boobooks!" />
        <br />
        <br />
        <div className="content">
          <p className="noto-sans-300">In the neighbourhood of one of the hotels bordering the Kanha National Park, there lived a cute little Booook.</p>
          <br />
          <div style={{width: "100%", alignItems: "center", justifyContent: "center", display: "flex", flexDirection: "column"}}>
            <img style={{border: "3px solid #DDDDDD", width: "80%", maxWidth: "600px"}} src={Blog6Img_1} />
            <p style={{color: "#AAAAAA", fontSize: "100%"}}>The neighbourhood Brown Boobook</p>
            <p style={{color: "#AAAAAA", fontSize: "90%"}}>© Madhur Vaidya</p>
          </div>
          <br />

          <p className="noto-sans-300">Its mornings began as the night approached, and it loved to catch insects and sing songs.</p>
          <br />

          <div style={{width: "100%", alignItems: "center", justifyContent: "center", display: "flex", flexDirection: "column"}}>
            <img style={{border: "3px solid #DDDDDD", width: "80%", maxWidth: "600px"}} src={Blog6Img} />
            <p style={{color: "#AAAAAA", fontSize: "100%"}}>The Brown Boobook turning back to look at the surroundings</p>
            <p style={{color: "#AAAAAA", fontSize: "90%"}}>© Madhur Vaidya</p>
          </div>
          <br />
          <br />

          <p className="noto-sans-300">The otherwise eeire silent nights of the forest rejoice in the song of the Boobook!</p>
          <br />

          <div style={{
              width: "100%",
              maxWidth: "600px",
              margin: "0 auto",
              colorScheme: "dark",
            }}
          >
            <div style={{
                width: "100%",
                display: "flex",
                justifyContent: "center",
              }}
            >
              <SpectrogramPlayer
                src={Blog6_Audio1}
                f_min={100}
                f_max={2000}
                n_mels={50}
                navigator
                specHeight={300}
                navHeight={80}
                transparent
                dark
                style={{
                  width: "100%",
                  border: "3px solid #DDDDDD",
                }}
              />
            </div>
            <p style={{ color: "#AAAAAA", textAlign: "center" }}>The song of the Brown Boobook</p>
            <p style={{ color: "#AAAAAA", textAlign: "center", fontSize: "90%" }}>© Madhur Vaidya</p>
          </div>

          <br />
          <br />
          <p className="noto-sans-300">One night, as the Boobook was singing from its favourite perch, a faint reply drifted through the darkness from somewhere deeper in the forest.</p>
          <br />
          <p className="noto-sans-300">The Boobook paused.</p>
          <br />
          <p className="noto-sans-300">Another call echoed back.</p>
          <br />
          <p className="noto-sans-300">Then once more.</p>
          <br />
          <p className="noto-sans-300">It wasn't the wind.</p>
          <br />

          <br />

          <div style={{
              width: "100%",
              maxWidth: "600px",
              margin: "0 auto",
              colorScheme: "dark",
            }}
          >
            <div style={{
                width: "100%",
                display: "flex",
                justifyContent: "center",
              }}
            >
              <SpectrogramPlayer
                src={Blog6_Audio2}
                f_min={100}
                f_max={2000}
                n_mels={50}
                navigator
                specHeight={300}
                navHeight={80}
                transparent
                dark
                style={{
                  width: "100%",
                  border: "3px solid #DDDDDD",
                }}
              />
            </div>
            <p style={{ color: "#AAAAAA", textAlign: "center" }}>The Brown Boobook singing, with another Brown Boobook singing in the background</p>
            <p style={{ color: "#AAAAAA", textAlign: "center", fontSize: "90%" }}>© Madhur Vaidya</p>
          </div>
          <br />
          <br />

          <p className="noto-sans-300">Another Boobook was nearby.</p>
          <br />
          <p className="noto-sans-300">That meant another Boobook was trying to infiltrate the territory! The neighbourhood Boobook became very alarmed.</p>
          <br />

          {/* Video 1 */}
          <div style={{width: "100%", alignItems: "center", justifyContent: "center", display: "flex", flexDirection: "column"}}>
            <iframe width="560" style={{maxWidth: "80%"}} height="315" src="https://www.youtube.com/embed/DabqrWsiwxs?si=4ZxwO1wNUEK9A4aQ" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
          </div>

          <br />
          <br />
          <p className="noto-sans-300">The intruder came and sat on the branch in front of the neighbourhood Boobook. For several minutes the two owls traded calls, each trying to out-sing the other. Neither was willing to back down. The calls grew louder, the pauses shorter.</p>
          <br />

          <br />
          <div style={{
              width: "100%",
              maxWidth: "600px",
              margin: "0 auto",
              colorScheme: "dark",
            }}
          >
            <div style={{
                width: "100%",
                display: "flex",
                justifyContent: "center",
              }}
            >
              <SpectrogramPlayer
                src={Blog6_Audio3}
                f_min={100}
                f_max={2000}
                n_mels={50}
                navigator
                specHeight={300}
                navHeight={80}
                transparent
                dark
                style={{
                  width: "100%",
                  border: "3px solid #DDDDDD",
                }}
              />
            </div>
            <p style={{ color: "#AAAAAA", textAlign: "center" }}>The Brown Boobook singing competition</p>
            <p style={{ color: "#AAAAAA", textAlign: "center", fontSize: "90%" }}>© Madhur Vaidya</p>
          </div>
          <br />
          <br />

          <p className="noto-sans-300">Suddenly, the confrontation spilled beyond song...</p>
          <br />
          <p className="noto-sans-300">The Boobooks started attacking each other! The fight intensified as they swooped down on the others, trying to hurt the other with their powerful talons.</p>
          <br />

          {/* Video 2 */}
          <div style={{width: "100%", alignItems: "center", justifyContent: "center", display: "flex", flexDirection: "column"}}>
            <iframe width="560" style={{maxWidth: "80%"}} height="315" src="https://www.youtube.com/embed/n9f5QE9-9fo?si=4ZxwO1wNUEK9A4aQ" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>
          </div>

          <br />
          <br />
          <p className="noto-sans-300">But the original Boobook was able to overpower the intruder! It chased the intruder away, cementing its position as the sole owl-controller of the area! The Boobook had successfully defended its territory from an intruder and its victory was visible on its proud face! Now its song was a clear reminder that the territory remained under its watch!</p>
          <br />

          <div style={{width: "100%", alignItems: "center", justifyContent: "center", display: "flex", flexDirection: "column"}}>
            <img style={{border: "3px solid #DDDDDD", width: "80%", maxWidth: "600px"}} src={Blog6Img_2} />
            <p style={{color: "#AAAAAA", fontSize: "100%"}}>The proud, glowing face of victory!</p>
            <p style={{color: "#AAAAAA", fontSize: "90%"}}>© Madhur Vaidya</p>
          </div>

          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
          <br />
        </div>
      </div>
    );
  }
}

export default Blog6;